"""Export a self-contained local review; no networking or Telegram controls."""
import argparse,json
from pathlib import Path
from .source_tracking import public_detail_url

TEMPLATE='''<!doctype html><html lang="uk"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AutoDeal · OLX — локальний перегляд</title>
<style>
:root{color-scheme:light;--ink:#16282e;--muted:#536b70;--line:#d7e3e0;--green:#126653;--amber:#875612}*{box-sizing:border-box}body{margin:0;background:#f3f7f5;color:var(--ink);font:15px/1.5 system-ui,sans-serif}main{max-width:1200px;margin:auto;padding:32px 24px 60px}.brand{font-weight:850;letter-spacing:-1px;font-size:30px;color:var(--green)}header{display:flex;justify-content:space-between;align-items:center;gap:20px}.badge{border:1px solid #cad9d4;border-radius:100px;padding:7px 13px;font-size:12px;font-weight:700}.eyebrow{text-transform:uppercase;letter-spacing:2px;font-size:11px;color:var(--muted);margin-top:40px}h1{font-size:clamp(26px,4vw,42px);line-height:1.15;letter-spacing:-1.2px;margin:10px 0 14px}p{max-width:850px}.muted{color:var(--muted)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:26px 0}.stat{background:#fff;border:1px solid var(--line);border-radius:16px;padding:18px}.stat strong{display:block;font-size:29px;color:var(--green)}.notice{border-left:4px solid #bf9451;background:#fff8e9;padding:16px 20px;border-radius:0 12px 12px 0;color:#5d461f}.controls{display:flex;flex-wrap:wrap;gap:12px;margin:28px 0 15px}input,select{font:inherit;padding:12px;border:1px solid #bbcfca;border-radius:10px;background:#fff;color:var(--ink)}input{flex:1;min-width:210px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:white;border:1px solid var(--line);border-radius:16px;padding:20px;display:flex;flex-direction:column;min-width:0}.tag{display:inline-block;font-size:11px;letter-spacing:1px;color:var(--muted)}h2{font-size:19px;line-height:1.3;margin:10px 0}.price{font-size:27px;font-weight:800;margin:9px 0}.attrs{color:var(--muted);font-size:13px;min-height:42px}.status{background:#fff3d9;color:#72501b;padding:8px 10px;font-size:12px;border-radius:8px;margin:15px 0 9px}.status.blocked{background:#fbeceb;color:#833e38}.reason{font-size:13px;margin:4px 0 12px}.numbers{display:grid;grid-template-columns:1fr 1fr;gap:8px;border-top:1px solid var(--line);padding-top:13px;font-size:12px}.numbers strong{display:block;font-size:17px;margin-top:3px}details{font-size:12px;margin:14px 0;color:var(--muted);overflow-wrap:anywhere}summary{cursor:pointer;font-weight:650}.link{display:block;border:1px solid #b2cec3;border-radius:9px;padding:9px 12px;text-align:center;margin-top:auto;color:var(--green);font-weight:700;text-decoration:none}.link:hover{background:#eef7f2}.empty{padding:30px;background:white;border:1px solid var(--line);border-radius:12px}footer{margin-top:30px;font-size:12px;color:var(--muted)}@media(max-width:920px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:590px){main{padding:22px 16px}header{align-items:flex-start}.badge{max-width:155px;text-align:center}.stats{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}.controls{flex-direction:column}h1{font-size:30px}}
</style><main><header><div class="brand">AutoDeal<span style="font-weight:450;color:#667e74"> / OLX</span></div><div class="badge">Локальний перегляд · без відправлень</div></header>
<div class="eyebrow">Перевірка перед інтеграцією</div><h1>Автомобілі та докази оцінки</h1><p class="muted">Збережені реальні оголошення, причини відбору й доступні аналоги. Цей перегляд не підключено до робочого бота. Дата знімка зазначена в кожній картці; це не поточна перевірка доступності оголошення.</p>
<div class="stats" id="stats"></div><div class="notice" id="notice"></div>
<div class="controls"><input id="query" type="search" placeholder="Пошук за ID, моделлю або роком" aria-label="Пошук"><select id="filter" aria-label="Результат перевірки"><option value="all">Усі оголошення</option><option value="held">Предмет або ціна потребують перевірки</option><option value="missing">Неповні характеристики</option><option value="sample">Недостатньо аналогів</option><option value="estimated">Експериментальна оцінка</option></select></div>
<p id="count" class="muted"></p><div id="cards" class="grid"></div><footer>Первинну публікацію та фактичні продажні ціни не підтверджено. Дані продавців не є незалежною перевіркою стану авто. Фільтри й платний доступ робочого AutoDeal не змінено.</footer></main>
<script id="data" type="application/json">__DATA__</script><script>
'use strict';
const data=JSON.parse(document.getElementById('data').textContent), cases=data.cases;
const labels={insufficient_comparables:'Недостатньо сумісних аналогів',missing_power_hp:'Не підтверджено потужність',missing_drive_type:'Не підтверджено привід',missing_generation:'Не підтверджено покоління',condition_unconfirmed:'Не підтверджено технічний стан',eligibility_not_allowed:'Предмет продажу не пройшов перевірку',ordinary_sale_not_corroborated:'Не підтверджено звичайний продаж',visible_sale_terms_missing_or_conflicting:'Умови продажу неповні або суперечливі',price_context_deposit:'Є ознаки першого внеску замість повної ціни',eur_fx_missing:'Немає перевіреної пари курсів EUR/USD',wide_dispersion:'Завеликий розкид цін',insufficient_after_outliers:'Замало аналогів після відсіву викидів'};
const names={wagon:'універсал',liftback:'ліфтбек',hatchback:'хетчбек',sedan:'седан',diesel:'дизель',petrol:'бензин',gas_petrol:'газ/бензин',manual:'механіка',automatic:'автомат',front:'передній привід',full:'повний привід',back:'задній привід'};
const eventNames={first_seen:'перше спостереження',update:'оновлення',raise:'підняття',reprice:'зміна видимої ціни'};
function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el}
function usd(v){return v==null?'—':new Intl.NumberFormat('uk-UA',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(v))}
function reason(v){return labels[v]||v}
const estimated=cases.filter(c=>c.assessment.status==='experimental_asking_estimate').length;
for(const [value,label] of [[cases.length,'повних сторінок'],[estimated,'експериментальних оцінок'],[Math.max(0,...cases.map(c=>c.assessment.sample)),'максимум аналогів'],[0,'Telegram-відправлень']]){const el=node('div',undefined,'stat');el.append(node('strong',String(value)),node('span',label,'muted'));document.getElementById('stats').append(el)}
document.getElementById('notice').textContent=estimated?'Оцінки нижче є дослідницькими орієнтирами цін пропозицій. Вони ще не підтверджують вигоду або готовність клієнтської доставки.':'Ринкова оцінка поки не готова. Вигоду не розраховано: сумісних аналогів або підтверджених характеристик недостатньо. Нульові оцінки не означають відсутність вигідних авто.';
function category(c){if(c.asking_evidence_reasons.length)return 'held';if(c.assessment.status==='experimental_asking_estimate')return 'estimated';if(c.assessment.reasons.some(r=>r.startsWith('missing_')||r==='condition_unconfirmed'))return 'missing';return 'sample'}
function card(c){const a=c.assessment,x=c.attributes,el=node('article',undefined,'card');el.append(node('span','OLX · '+c.id,'tag'),node('h2',c.title||'Автомобіль'),node('div',(['converted_uah','converted_eur'].includes(c.price.reason)?'≈ ':'')+usd(c.price.usd_amount),'price'));const attrs=[x.year,x.engine_cc?String(x.engine_cc/1000)+' л':null,names[x.fuel],names[x.transmission],names[x.body],x.mileage_km?new Intl.NumberFormat('uk-UA').format(x.mileage_km)+' км':null,names[x.drive_type],x.power_hp?x.power_hp+' к.с.':null].filter(Boolean).join(' · ');el.append(node('div',attrs,'attrs'));const held=category(c)==='held';el.append(node('div',held?'Утримано для перевірки':a.status==='experimental_asking_estimate'?'Експериментальна оцінка':'Вигідність не підтверджена','status'+(held?' blocked':'')));el.append(node('p',[...new Set([...a.reasons,...(c.price.status==='pending'?[c.price.reason]:[])])].map(reason).join('. '),'reason'));const nums=node('div',undefined,'numbers');for(const [label,value] of [['Ринковий орієнтир',usd(a.reference_usd)],['Сумісні аналоги',a.sample+' / '+a.required_sample]]){const n=node('div',label);n.append(node('strong',value));nums.append(n)}el.append(nums);const details=node('details');details.append(node('summary','Дані та пояснення'));const observedEvents=(c.newness.event_kinds||[]).map(v=>eventNames[v]||v).join(', ')||'немає підтверджених змін';const values=[['Знімок',new Date(c.observed_at*1000).toLocaleString('uk-UA',{timeZone:'Europe/Kyiv'})+' · Київ'],['Видима ціна OLX',c.price.input_amount+' '+c.price.input_currency],['Курс',c.price.fx?c.price.fx.rate+' UAH/USD, '+c.price.fx.kind:c.price.input_currency==='USD'?'Не потрібен для ціни в USD':'Очікується перевірена валютна пара'],['Діапазон',a.range_usd?usd(a.range_usd.low)+' – '+usd(a.range_usd.high)+' (IQR)':'Не визначений'],['Вигода',a.methods?.median?.discount_percent!=null?Number(a.methods.median.discount_percent).toFixed(1)+'% — лише експеримент':'Не підтверджена'],['ID аналогів',a.used_comparables.map(v=>v.id).join(', ')||'Немає'],['Перевірка предмета',c.offer.status||'Невідомо'],['Події спостереження',observedEvents],['Нова публікація','Не підтверджена']];for(const [k,v] of values)details.append(node('p',k+': '+v));el.append(details);if(c.url){const link=node('a','Відкрити оголошення OLX','link');link.href=c.url;link.target='_blank';link.rel='noopener noreferrer';el.append(link)}return el}
function render(){const q=document.getElementById('query').value.toLocaleLowerCase('uk'),f=document.getElementById('filter').value;const selected=cases.filter(c=>(f==='all'||category(c)===f)&&(c.id+' '+c.title+' '+c.attributes.year).toLocaleLowerCase('uk').includes(q));const root=document.getElementById('cards');root.replaceChildren(...selected.map(card));if(!selected.length)root.append(node('div','За цим фільтром нічого не знайдено.','empty'));document.getElementById('count').textContent='Показано '+selected.length+' із '+cases.length}
document.getElementById('query').addEventListener('input',render);document.getElementById('filter').addEventListener('change',render);render();
</script></html>'''


def export(result):
    if result.get('mode')!='isolated_review_only':raise ValueError('Isolated review required')
    safe={'cases':result['cases']}
    for c in safe['cases']:
        if not public_detail_url(c['url']):raise ValueError('Unexpected listing URL')
    payload=json.dumps(safe,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    return TEMPLATE.replace('__DATA__',payload)


def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--input',required=True);ap.add_argument('--output',required=True);args=ap.parse_args()
    result=json.loads(Path(args.input).read_text());Path(args.output).write_text(export(result));print(json.dumps({'cases':len(result['cases']),'telegram_calls':0}))

if __name__=='__main__':main()
